func (q *Queries) TakenFullCodes(ctx context.Context, arg TakenFullCodesParams) ([]string, error) {
	rows, err := q.db.Query(ctx, takenFullCodes, arg.FullCodes, arg.Excluded)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var full_code string
		if err := rows.Scan(&full_code); err != nil {
			return nil, err
		}
		items = append(items, full_code)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateLocation = `-- name: UpdateLocation :one
UPDATE inventory.locations
SET parent_id = $1, kind = $2, code = $3, name = $4, sort_order = $5,
    status = $6, full_code = $7, ancestors = $8::bigint[], depth = $9,
    revision = revision + 1, updated_at = $10::timestamptz
WHERE id = $11
RETURNING id, site_id, parent_id, kind, code, name, sort_order, status, full_code, ancestors, depth, revision, created_at, updated_at
`

type UpdateLocationParams struct {
	ParentID  *int64
	Kind      string
	Code      string
	Name      *string
	SortOrder int32
	Status    string
	FullCode  string
	Ancestors []int64
	Depth     int16
	Now       time.Time
	ID        int64
}

// UpdateLocation replaces one location's fields, its place in the tree
// included, and moves its revision on.
func (q *Queries) UpdateLocation(ctx context.Context, arg UpdateLocationParams) (InventoryLocation, error) {
	row := q.db.QueryRow(ctx, updateLocation,
		arg.ParentID,
		arg.Kind,
		arg.Code,
		arg.Name,
		arg.SortOrder,
		arg.Status,
		arg.FullCode,
		arg.Ancestors,
		arg.Depth,
		arg.Now,
		arg.ID,
	)
	var i InventoryLocation
	err := row.Scan(
		&i.ID,
		&i.SiteID,
		&i.ParentID,
		&i.Kind,
		&i.Code,
		&i.Name,
		&i.SortOrder,
		&i.Status,
		&i.FullCode,
		&i.Ancestors,
		&i.Depth,
		&i.Revision,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
